namespace sv_92a4ba1720d541c38b78b46a96c025fb.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit (per-user) theme state.
/// All interactive components on the same circuit share this instance.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChanged;

    public void SetTheme(ThemeMode theme)
    {
        Theme = theme;
        NotifyChanged();
    }

    public void SetAccentColor(string color)
    {
        AccentColor = color;
        NotifyChanged();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@* This component is rendered as an interactive island inside the static layout *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" title="Current theme">
    @GetThemeIcon() <span style="color: @ThemeService.AccentColor;">●</span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += StateHasChanged;
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" value="@ThemeService.Theme" @onchange="OnThemeChanged">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor" @onchange="OnAccentChanged" />
</div>

<p>
    Current: <strong>@ThemeService.Theme</strong> /
    <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += StateHasChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeService.SetTheme(mode);
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= StateHasChanged;
    }
}

